class Solution {
public:
    int minOperations(vector<int>& nums) {
        int n = nums.size();
        if (n < 3) return -1;
        int mx = *max_element(nums.begin(), nums.end());
        int maxV = mx + n;                     // upper bound for final values
        const long long INF = (1LL<<60);

        // left DP
        vector<vector<long long>> left(n, vector<long long>(maxV + 1, INF));
        for (int v = 1; v <= maxV; ++v) {
            left[0][v] = llabs((long long)nums[0] - v);
        }
        for (int i = 1; i < n; ++i) {
            long long best = INF;
            for (int v = 1; v <= maxV; ++v) {
                // best = min_{u < v} left[i-1][u]
                best = min(best, left[i-1][v-1]);
                if (best < INF)
                    left[i][v] = best + llabs((long long)nums[i] - v);
            }
        }

        // right DP (strictly decreasing to the right)
        vector<vector<long long>> right(n, vector<long long>(maxV + 1, INF));
        for (int v = 1; v <= maxV; ++v) {
            right[n-1][v] = llabs((long long)nums[n-1] - v);
        }
        for (int i = n - 2; i >= 0; --i) {
            long long best = INF;
            for (int v = 1; v <= maxV; ++v) {
                best = min(best, right[i+1][v-1]);   // u < v for decreasing sequence
                if (best < INF)
                    right[i][v] = best + llabs((long long)nums[i] - v);
            }
        }

        long long ans = INF;
        for (int peak = 1; peak <= n - 2; ++peak) {
            for (int v = 1; v <= maxV; ++v) {
                if (left[peak][v] == INF || right[peak][v] == INF) continue;
                long long total = left[peak][v] + right[peak][v] - llabs((long long)nums[peak] - v);
                ans = min(ans, total);
            }
        }
        return (ans >= INF/2) ? -1 : (int)ans;
    }
};
